-- ============================================================
-- seed_data.sql — Skillor query-timing benchmark dataset
-- Project : Skillor — Skill Exchange Platform
-- Purpose : Reproducible mid-scale dataset for EXPLAIN (ANALYZE, BUFFERS)
--           runs against 03_schema.sql (PostgreSQL 14+).
-- Scale   : 200 users | 60 skills | 815 user_skills | 300 matches |
--           297 exchange_requests | 233 conversations | 3019 messages |
--           358 reviews | 1002 notifications
-- Notes   : * 'JavaScript' is intentionally NOT seeded so query Q37
--             (INSERT INTO skills) succeeds despite the UNIQUE constraint.
--           * user 1 never teaches skill 1 and never learns skill 2 so
--             Q38 / Q39 INSERTs succeed.
--           * exchange_requests id=1 is 'pending' (sender = user 1) for Q41.
--           * notifications id=1 (user 1) and messages id=1 are unread for Q42/Q43/Q45.
--           * Run on a FRESH schema so identity ids are 1..N in insert order.
-- Usage   : psql -d skillor -f seed_data.sql
-- ============================================================

BEGIN;

